{
  "id": "p_001",
  "summary": "Diseño de API REST minimalista para gestión de tareas (CRUD) con esquemas JSON para peticiones, respuestas y errores.",
  "approach": "Se definen 5 endpoints estándar REST sobre el recurso /tasks. Se utilizan verbos HTTP (GET, POST, PUT, DELETE) y códigos de estado estándar (200, 201, 204, 400, 404). Los esquemas JSON se tipan con UUID para IDs y enums para estados. El diseño completo se proporciona en el artifact api-design.ts como un objeto JSON exportado.",
  "tradeoffs": [
    "Usar PUT en lugar de PATCH simplifica la validación pero requiere enviar el objeto completo en cada actualización.",
    "Omitir paginación en GET /tasks cumple con el requisito minimalista pero no escalará para grandes volúmenes de datos."
  ],
  "evidence": [
    "RFC 7231 para semántica de verbos HTTP.",
    "JSON Schema Draft 7 para la validación de payloads."
  ],
  "artifacts": [
    {
      "kind": "api-design.ts",
      "language": "typescript",
      "source": "export const apiDesign = {
  "resource": "tasks",
  "endpoints": [
    {
      "method": "GET",
      "path": "/tasks",
      "description": "Listar todas las tareas",
      "request": null,
      "response": {
        "status": 200,
        "schema": {
          "type": "array",
          "items": { "$ref": "#/schemas/Task" }
        }
      }
    },
    {
      "method": "POST",
      "path": "/tasks",
      "description": "Crear una nueva tarea",
      "request": {
        "schema": {
          "type": "object",
          "required": ["title"],
          "properties": {
            "title": { "type": "string" },
            "description": { "type": "string" },
            "status": { "type": "string", "enum": ["pending", "in_progress", "done"] }
          }
        }
      },
      "response": {
        "status": 201,
        "schema": { "$ref": "#/schemas/Task" }
      }
    },
    {
      "method": "GET",
      "path": "/tasks/{id}",
      "description": "Obtener una tarea por ID",
      "request": {
        "params": { "id": { "type": "string", "format": "uuid" } }
      },
      "response": {
        "status": 200,
        "schema": { "$ref": "#/schemas/Task" }
      }
    },
    {
      "method": "PUT",
      "path": "/tasks/{id}",
      "description": "Actualizar una tarea existente",
      "request": {
        "params": { "id": { "type": "string", "format": "uuid" } },
        "schema": {
          "type": "object",
          "required": ["title", "status"],
          "properties": {
            "title": { "type": "string" },
            "description": { "type": "string" },
            "status": { "type": "string", "enum": ["pending", "in_progress", "done"] }
          }
        }
      },
      "response": {
        "status": 200,
        "schema": { "$ref": "#/schemas/Task" }
      }
    },
    {
      "method": "DELETE",
      "path": "/tasks/{id}",
      "description": "Eliminar una tarea",
      "request": {
        "params": { "id": { "type": "string", "format": "uuid" } }
      },
      "response": {
        "status": 204,
        "schema": null
      }
    }
  ],
  "schemas": {
    "Task": {
      "type": "object",
      "properties": {
        "id": { "type": "string", "format": "uuid" },
        "title": { "type": "string" },
        "description": { "type": "string" },
        "status": { "type": "string", "enum": ["pending", "in_progress", "done"] },
        "created_at": { "type": "string", "format": "date-time" }
      },
      "required": ["id", "title", "status", "created_at"]
    },
    "Error": {
      "type": "object",
      "properties": {
        "error": {
          "type": "object",
          "properties": {
            "code": { "type": "string" },
            "message": { "type": "string" }
          },
          "required": ["code", "message"]
        }
      }
    }
  }
};"
    }
  ]
}
